let slots = Mutex::new(8usize);
let cv = Condvar::new();

// acquire
let mut permits = slots.lock().unwrap();
permits = cv.wait_while(permits, |p| *p == 0).unwrap();
*permits -= 1;
drop(permits);

// release
let mut permits = slots.lock().unwrap();
*permits += 1;
drop(permits);
cv.notify_one();
